// stateutil.Merkleize (trie_helpers.go lines 254-279)
func Merkleize(leaves [][]byte) [][][]byte {
    hashFunc := hash.CustomSHA256Hasher()
    layers := make([][][]byte, ssz.Depth(uint64(len(leaves)))+1)
    for len(leaves)%32 != 0 {
        leaves = append(leaves, make([]byte, 32))
    }
    currentLayer := leaves
    layers[0] = currentLayer
    i := 1
    for len(currentLayer) > 1 && i < len(layers) {
        layer := make([][]byte, 0)
        for i := 0; i < len(currentLayer); i += 2 {
            hashedChunk := hashFunc(append(currentLayer[i], currentLayer[i+1]...))
            layer = append(layer, hashedChunk[:])
        }
        currentLayer = layer
        layers[i] = currentLayer
        i++
    }
    return layers
}

// recomputeRoot (setters_misc.go lines 161-191)
func (b *BeaconState) recomputeRoot(idx int) {
    hashFunc := hash.CustomSHA256Hasher()
    layers := b.merkleLayers
    currentIndex := idx
    root := b.merkleLayers[0][idx]
    for i := 0; i < len(layers)-1; i++ {
        isLeft := currentIndex%2 == 0
        neighborIdx := currentIndex ^ 1
        neighbor := make([]byte, 32)
        if layers[i] != nil && len(layers[i]) != 0 && neighborIdx < len(layers[i]) {
            neighbor = layers[i][neighborIdx]
        }
        if isLeft {
            parentHash := hashFunc(append(root, neighbor...))
            root = parentHash[:]
        } else {
            parentHash := hashFunc(append(neighbor, root...))
            root = parentHash[:]
        }
        parentIdx := currentIndex / 2
        layers[i+1][parentIdx] = root
        currentIndex = parentIdx
    }
    b.merkleLayers = layers
}
